'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { LRUCache } = require('./src/lru');

test('capacity accepts only positive integer Numbers', () => {
  for (const capacity of [0, -0, -1, 1.5, Infinity, -Infinity, NaN, '2', undefined, null, true, 2n, {}, new Number(2), Symbol('capacity')]) {
    assert.throws(() => new LRUCache(capacity), RangeError);
  }
  assert.throws(() => new LRUCache(), RangeError);
  for (const capacity of [1, 2, Number.MAX_VALUE]) {
    const cache = new LRUCache(capacity);
    cache.set('key', capacity);
    assert.equal(cache.get('key'), capacity);
  }
});

test('Map key semantics preserve identity, NaN, and signed zero', () => {
  const object = {};
  const other = {};
  const symbol = Symbol('key');
  const value = {};
  const cache = new LRUCache(10);
  cache.set(object, value).set(other, 'other').set(symbol, null)
    .set(NaN, 'nan').set(-0, 'zero').set(undefined, false)
    .set(null, 0).set(1n, 'bigint').set('1', 'string');
  assert.equal(cache.get(object), value);
  assert.equal(cache.get(other), 'other');
  assert.equal(cache.has({}), false);
  assert.equal(cache.get(symbol), null);
  assert.equal(cache.get(Number('not a number')), 'nan');
  assert.equal(cache.get(+0), 'zero');
  assert.equal(cache.get(undefined), false);
  assert.equal(cache.get(null), 0);
  assert.equal(cache.get(1n), 'bigint');
  assert.equal(cache.get('1'), 'string');
  cache.set(+0, 'updated');
  assert.equal(cache.size, 9);
  assert.equal(cache.get(-0), 'updated');
});

test('undefined values refresh and undefined keys can be evicted', () => {
  const cache = new LRUCache(2);
  cache.set('a', undefined).set('b', 2);
  assert.equal(cache.get('a'), undefined);
  cache.set('c', 3);
  assert.equal(cache.has('a'), true);
  assert.equal(cache.has('b'), false);
  const single = new LRUCache(1);
  single.set(undefined, undefined).set('next', 1);
  assert.equal(single.has(undefined), false);
  assert.equal(single.get('next'), 1);
  assert.equal(single.size, 1);
});

test('updates refresh without increasing size or evicting another entry', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1).set('b', 2);
  assert.equal(cache.set('a', 3), cache);
  assert.equal(cache.size, 2);
  assert.equal(cache.has('b'), true);
  cache.set('c', 4);
  assert.equal(cache.has('b'), false);
  assert.equal(cache.get('a'), 3);
  assert.equal(cache.get('c'), 4);
});

test('has, misses, and deletion preserve surviving recency', () => {
  const cache = new LRUCache(3);
  cache.set('a', 1).set('b', 2).set('c', 3);
  assert.equal(cache.has('a'), true);
  assert.equal(cache.has('missing'), false);
  assert.equal(cache.get('missing'), undefined);
  assert.equal(cache.delete('b'), true);
  assert.equal(cache.delete('b'), false);
  cache.set('d', 4).set('e', 5);
  assert.equal(cache.has('a'), false);
  assert.equal(cache.get('c'), 3);
  assert.equal(cache.get('d'), 4);
  assert.equal(cache.get('e'), 5);
  assert.equal(cache.size, 3);
});

test('cache instances have independent entries and recency', () => {
  const first = new LRUCache(1);
  const second = new LRUCache(2);
  first.set('a', 1);
  second.set('a', 2).set('b', 3);
  first.set('c', 4);
  assert.equal(first.has('a'), false);
  assert.equal(second.get('a'), 2);
  assert.equal(second.delete('a'), true);
  assert.equal(first.get('c'), 4);
  assert.equal(first.size, 1);
  assert.equal(second.size, 1);
});

